import random

def is_triangle(a, b, c):
    return a + b > c and a + c > b and b + c > a

def count_not_triangles(triangles):
    n = len(triangles)
    gs = sorted([t[0] for t in triangles], reverse=True)
    ps = sorted([t[1] for t in triangles], reverse=True)
    os = sorted([t[2] for t in triangles], reverse=True)
    count = 0
    for i in range(n):
        if not is_triangle(gs[i], ps[i], os[i]):
            count += 1
    return count

def solve_better(n, iterations=100000):
    max_not_triangles = 0
    for _ in range(iterations):
        triangles = []
        for _ in range(n):
            a = random.uniform(1, 100)
            b = random.uniform(1, 100)
            c = random.uniform(abs(a-b) + 0.01, a + b - 0.01)
            # To ensure we don't have degenerate triangles, we'll add a small epsilon
            # But the problem says non-degenerate.
            triangles.append((a, b, c))

        res = count_not_triangles(triangles)
        if res > max_not_triangles:
            max_not_triangles = res
    return max_not_triangles

for n in range(1, 8):
    print(f"n={n}, max={solve_better(n, 200000)}")

