def find_max_for_n_with_triangles(n, iterations=500000):
    max_not_triangles = 0
    for _ in range(iterations):
        triangles = []
        for _ in range(n):
            a = random.uniform(0.1, 100)
            b = random.uniform(0.1, 100)
            # To ensure it's a triangle, c is in (abs(a-b), a+b)
            c = random.uniform(abs(a-b) + 0.0001, a + b - 0.0001)
            triangles.append((a, b, c))

        res = count_not_triangles(triangles)
        if res > max_not_triangles:
            max_not_triangles = res
    return max_not_triangles

for n in range(1, 21):
